#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <iomanip>
#include <string>
#include <vector>
using Clock=std::chrono::steady_clock;
static std::size_t observe(const std::shared_ptr<Node>& h){std::size_t count=0;for(auto p=h.get();p;p=p->n.get())++count;return count;}
int main(int argc,char**argv){
 if(argc!=5)return 2;const std::string op=argv[1];const std::size_t n=std::strtoull(argv[2],nullptr,0);const int reps=std::atoi(argv[3]);const bool shared=std::atoi(argv[4]);double ns=0;std::uint64_t sum=0;
 for(int rep=0;rep<reps;++rep){
  std::shared_ptr<Node> h;std::vector<std::shared_ptr<Node>> refs;
  if(op=="push"){
   if(shared)refs.reserve(n);
   auto begin=Clock::now();for(std::size_t i=0;i<n;++i){if(shared)refs.push_back(h);push_front_node(h);}auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();sum+=observe(h);
  }else{
   h=make_chain(n);sum+=observe(h);
   if(shared){refs.reserve(n);for(auto p=h;p;p=p->n)refs.push_back(p);}
   if(op=="pop"){
    auto begin=Clock::now();for(std::size_t i=0;i<n;++i)sum+=pop_front_node(h);auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();sum+=!h;
   }else if(op=="clear"){
    std::weak_ptr<Node> weak=h;auto begin=Clock::now();clear_chain(h);auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();sum+=weak.expired();
   }else if(op=="size"){
    auto begin=Clock::now();for(int i=0;i<8;++i)sum+=chain_size(h);auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();
   }else if(op=="tail"){
    auto begin=Clock::now();for(int i=0;i<8;++i)sum+=chain_tail(h)!=nullptr;auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();
   }else if(op=="nth"){
    auto begin=Clock::now();for(int i=0;i<8;++i)sum+=chain_nth(h,n/2+(i&1))!=nullptr;auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();
   }else if(op=="reverse"){
    auto begin=Clock::now();for(int i=0;i<4;++i)h=reverse_chain(std::move(h));auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();sum+=observe(h);
   }else if(op=="clone"){
    auto begin=Clock::now();auto clone=clone_chain(h);auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();sum+=observe(clone);
   }else if(op=="cycle"){
    auto tail=chain_tail(h);auto entry=chain_nth(h,n/3);tail->n=entry;
    auto begin=Clock::now();sum+=cycle_entry(h)==entry.get();sum+=break_cycle(h);auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();sum+=observe(h);
   }else return 3;
  }
 }
 std::cout<<std::setprecision(17)<<ns<<' '<<sum<<'\n';
}

