#include <cstddef>
#include <cstdlib>
#include <new>
#include <stdexcept>
#include <iostream>
static bool fail_next=false;
void* operator new(std::size_t size){if(fail_next){fail_next=false;throw std::bad_alloc();}if(auto p=std::malloc(size?size:1))return p;throw std::bad_alloc();}
void operator delete(void*p)noexcept{std::free(p);}
void operator delete(void*p,std::size_t)noexcept{std::free(p);}
#include HEADER
static unsigned checks=0;
static void require(bool b){++checks;if(!b)std::abort();}
static void fail_push(std::shared_ptr<Node>&head){Node* before=head.get();Node* next=head?head->n.get():nullptr;long refs=head.use_count();bool caught=false;fail_next=true;try{push_front_node(head);}catch(const std::bad_alloc&){caught=true;}require(caught&&!fail_next);require(head.get()==before&&head.use_count()==refs);require((head?head->n.get():nullptr)==next);}
int main(){
 std::shared_ptr<Node> h;fail_push(h);h=make_chain(32);fail_push(h);require(chain_size(h)==32);auto alias=h;fail_push(h);require(alias==h&&chain_size(alias)==32);auto parent=make_node(h);fail_push(parent->n);require(parent->n==h);
 auto cyclic=make_node();cyclic->n=cyclic;fail_push(cyclic);require(cyclic->n==cyclic);require(break_cycle(cyclic));
 auto old=h;push_front_node(h);require(h->n==old&&chain_size(h)==33);require(old.use_count()==4); // alias,parent,old,new head
 std::cout<<"PASS "<<checks<<" allocation failure and preservation checks\n";
}

