from pathlib import Path
import subprocess,json,random,statistics,hashlib,shutil,fcntl
b=Path(__file__).resolve().parent;data={'build':[],'rows':[],'summary':{},'cpu':18,'flags':'C++23 -O2 -DSKIP_RUNTIME_CHECKS','variants':['baseline','control','push','pop','both']}
work=[]
for n,reps in [(1,100000),(2,100000),(32,10000),(100000,5),(1000000,1)]:
 for op in ['push','pop','clear']:
  for shared in ([0,1]if n!=1000000 else [0]):work.append((op,n,reps,shared))
for n,reps in [(32,10000),(100000,3)]:
 for op in ['size','tail','nth','reverse','clone','cycle']:work.append((op,n,reps,0))
data['workloads']=work
for cc,compiler in [('gcc',['/usr/bin/g++']),('clang',['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'])]:
 for v in data['variants']:
  exe=b/(cc+'-'+v)
  if v=='control':shutil.copyfile(b/(cc+'-baseline'),exe);exe.chmod(0o755);cmd=None
  else:
   cmd=['taskset','-c','22',*compiler,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(b/(v+'.hpp'))+'"',str(b/'bench.cpp'),'-o',str(exe)];q=subprocess.run(cmd,capture_output=True);assert not q.returncode,q.stderr.decode()
  data['build'].append({'compiler':cc,'variant':v,'command':cmd,'binary_sha256':hashlib.sha256(exe.read_bytes()).hexdigest()})
 print('compiled',cc,flush=True)
with open('/tmp/sirkit_node_perf18.lock','w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in ['gcc','clang']:
  for i,(op,n,reps,shared)in enumerate(work):
   for rep in range(5):
    variants=data['variants'].copy();random.Random(i*51+rep).shuffle(variants);checksums=set()
    for v in variants:
     q=subprocess.check_output(['taskset','-c','18',str(b/(cc+'-'+v)),op,str(n),str(reps),str(shared)],text=True).split();checksums.add(q[1]);data['rows'].append({'compiler':cc,'variant':v,'operation':op,'n':n,'reps':reps,'shared':bool(shared),'round':rep,'ns':float(q[0]),'checksum':q[1]})
    assert len(checksums)==1,(cc,op,n,shared,checksums)
  summary={}
  for op,n,reps,shared in work:
   med={v:statistics.median(x['ns']for x in data['rows']if x['compiler']==cc and x['variant']==v and x['operation']==op and x['n']==n and x['shared']==bool(shared))for v in data['variants']};summary[f'{op}_{n}_{shared}']={'median_ns':med,'ratios':{v:t/med['baseline']for v,t in med.items()}}
  data['summary'][cc]=summary;(b/'results.json').write_text(json.dumps(data,indent=2)+'\n');print('measured',cc,flush=True)
print('DONE',flush=True)

