    for wi,(n,reps,shared)in enumerate(workloads):
     for rep in range(9):
      variants=['baseline','control','push'];random.Random(wi*59+rep).shuffle(variants);sums=set()
      for v in variants:
       exe=b/f'{cc}-{skip}-{op}-{v}';q=subprocess.check_output(['taskset','-c','18',str(exe),op,str(n),str(reps),str(shared)],text=True).split();sums.add(q[1]);data['rows'].append({'compiler':cc,'skip':skip,'op':op,'n':n,'shared':shared,'reps':reps,'round':rep,'variant':v,'ns':float(q[0]),'checksum':q[1]})
      assert len(sums)==1
  ss={}
  for skip in [False,True]:
   for x in data['rows']:
    if x['compiler']!=cc or x['skip']!=skip:continue
    key=f"{'skip'if skip else'checked'}_{x['op']}_{x['n']}_{x['shared']}"
    if key in ss:continue
    med={v:statistics.median(y['ns']for y in data['rows']if all(y[k]==x[k]for k in ['compiler','skip','op','n','shared'])and y['variant']==v)for v in ['baseline','control','push']};ss[key]={'median_ns':med,'ratio':med['push']/med['baseline'],'control_ratio':med['control']/med['baseline']}
  data['summary'][cc]=ss;(b/'retake-results.json').write_text(json.dumps(data,indent=2)+'\n');print('measured retake',cc,flush=True)

